            {'title': 'Medical questionnaire & clearance'   , 'category': 'Getting Started'      , 'start_offset_minutes': 3 * DAY,  'duration_minutes': 4 * DAY,  'notes': 'Complete the diver medical questionnaire. Any \'yes\' answer (asthma, heart, ear/sinus issues, etc.) requires a physician\'s sign-off before in-water training.', 'percent_complete': 0, 'depends_on': [0]},
            {'title': 'Enroll & receive eLearning access'   , 'category': 'Getting Started'      , 'start_offset_minutes': 1 * WEEK, 'duration_minutes': 1 * DAY,  'notes': 'Pay course fee and get your online login. Rental gear sizing (mask, fins, wetsuit) often happens now.', 'percent_complete': 0, 'depends_on': [1]},
            {'title': 'Complete eLearning modules & quizzes', 'category': 'Knowledge Development', 'start_offset_minutes': 8 * DAY,  'duration_minutes': 1 * WEEK, 'notes': 'About 8-12 hours of self-paced video and reading across 5 sections, each with a knowledge review quiz. Work through it over several evenings.', 'percent_complete': 0, 'depends_on': [2]},
            {'title': 'Pass final theory exam'              , 'category': 'Knowledge Development', 'start_offset_minutes': 15 * DAY, 'duration_minutes': 1 * DAY,  'notes': 'Multiple-choice final exam (75% pass mark). Bring proof of completion to your first pool session.', 'percent_complete': 0, 'depends_on': [3]},
            {'title': 'Confined-water pool sessions'        , 'category': 'Confined Water'       , 'start_offset_minutes': 3 * WEEK, 'duration_minutes': 2 * DAY,  'notes': '5 confined-water dives in a pool: mask clearing, regulator recovery, buoyancy, and out-of-air drills. Usually split over 1-2 days under direct instructor supervision.', 'percent_complete': 0, 'depends_on': [4]},
            {'title': 'Pack & check gear before checkout'   , 'category': 'Open Water Dives'     , 'start_offset_minutes': 4 * WEEK, 'duration_minutes': 1 * DAY,  'notes': 'Confirm rental kit, exposure suit, and logbook. Review dive site logistics, weather, and the buddy plan for the weekend.', 'percent_complete': 0, 'depends_on': [5]},
            {'title': 'Open-water dives 1-2 (Day 1)'        , 'category': 'Open Water Dives'     , 'start_offset_minutes': 5 * WEEK, 'duration_minutes': 1 * DAY,  'notes': 'First 2 of 4 certification dives at a real site, demonstrating pool skills in open water. Max training depth 18m/60ft.', 'percent_complete': 0, 'depends_on': [6]},
            {'title': 'Open-water dives 3-4 (Day 2)'        , 'category': 'Open Water Dives'     , 'start_offset_minutes': 36 * DAY, 'duration_minutes': 1 * DAY,  'notes': 'Final 2 certification dives, including navigation and a controlled emergency swimming ascent. Must fall on a separate day from dives 1-2.', 'percent_complete': 0, 'depends_on': [7]},
            {'title': 'Get certified & log dives'           , 'category': 'Certified & Beyond'   , 'start_offset_minutes': 37 * DAY, 'duration_minutes': 3 * DAY,  'notes': 'Instructor signs off and submits paperwork; digital/plastic C-card follows. You\'re certified to dive to 18m/60ft with a buddy.', 'percent_complete': 0, 'depends_on': [8]},
